import{_ as a,C as i,o as n,c as l,aj as r,E as o,j as t,a as c}from"./chunks/framework.DkvuVDKz.js";const v=JSON.parse('{"title":"ImageViewer 图片预览","description":"","frontmatter":{},"headers":[],"relativePath":"components/image-viewer.md","filePath":"components/image-viewer.md","lastUpdated":1789272501000}'),g={name:"components/image-viewer.md"};function h(s,d,b,p,u,m){const e=i("XhDemo");return n(),l("div",null,[d[0]||(d[0]=r('<h1 id="imageviewer-图片预览" tabindex="-1">ImageViewer 图片预览 <a class="header-anchor" href="#imageviewer-图片预览" aria-label="Permalink to &quot;ImageViewer 图片预览&quot;">​</a></h1><p>点开看大图：全屏浮层里可以缩放、旋转、翻转与翻页。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/image-viewer" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/image-viewer.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/image-viewer" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/image-viewer" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/image-viewer.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>触发器打开全屏看片：滚轮缩放、拖拽平移、工具条给缩放/旋转/翻转/归零，Esc 或点遮罩关闭</p>',5)),o(e,{src:"image-viewer/01-basic"}),d[1]||(d[1]=r('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;image-viewer&quot;</code>：<code>trigger</code> · <code>backdrop</code> · <code>positioner</code> · <strong><code>content</code></strong> · <code>viewport</code> · <strong><code>image</code></strong> · <code>toolbar</code> · <code>zoom-in-trigger</code> · <code>zoom-out-trigger</code> · <code>rotate-left-trigger</code> · <code>rotate-right-trigger</code> · <code>flip-horizontal-trigger</code> · <code>flip-vertical-trigger</code> · <code>reset-trigger</code> · <code>prev-trigger</code> · <code>next-trigger</code> · <code>counter</code> · <code>close-trigger</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="相册与翻页" tabindex="-1">相册与翻页 <a class="header-anchor" href="#相册与翻页" aria-label="Permalink to &quot;相册与翻页&quot;">​</a></h3><p>多张图共用一个看片浮层：两侧按钮或方向键翻页、计数报「第几张」，缩放旋转在换图时归零</p>',6)),o(e,{src:"image-viewer/02-album"}),d[2]||(d[2]=t("h3",{id:"受控与文案",tabindex:"-1"},[c("受控与文案 "),t("a",{class:"header-anchor",href:"#受控与文案","aria-label":'Permalink to "受控与文案"'},"​")],-1)),d[3]||(d[3]=t("p",null,"open 与 index 双受控；translations 换工具条的可及名与计数文案",-1)),o(e,{src:"image-viewer/03-controlled"}),d[4]||(d[4]=t("h3",{id:"双指缩放",tabindex:"-1"},[c("双指缩放 "),t("a",{class:"header-anchor",href:"#双指缩放","aria-label":'Permalink to "双指缩放"'},"​")],-1)),d[5]||(d[5]=t("p",null,"触屏上两指撑开放大、捏合缩小，单指平移；缩放夹在 minScale 与 maxScale 之间",-1)),o(e,{src:"image-viewer/04-gesture"}),d[6]||(d[6]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>图片细节重要（截图、单据、商品图）。</li><li>一组图需要连续浏览。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>图本身已经足够大：不必再套一层。</li><li>需要的是编辑（裁切、标注）：这是只读的查看器。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li><code>collection</code> 给整组图，<code>index</code> 决定当前哪一张，<code>loop</code> 决定是否回绕。</li><li>缩放步长与上下限可调。</li><li>触屏上两指撑开放大、捏合缩小，单指平移；缩放以两指中点为锚。</li><li>关闭后焦点归还触发器。</li><li>逻辑关闭立即退出交互与可访问树；内容和遮罩完成退场后才释放模态资源，重开会撤销旧退场。</li><li>底部控件带是一组有名字的控件，每颗钮各占一个 Tab 位；左右方向键与 Home/End 留给翻页，条里条外都一样。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>触发器用<a href="./image">图片</a>；一组<a href="./image">图片</a>共用一个预览层。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>显示&quot;第几张 / 共几张&quot;，用户才知道还有多少。</li><li>工具栏按钮全部给可及名字：它们只有图标。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>打开后 Escape 关不掉。</li><li>缩放后没有复位入口。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-image-viewer&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhImageViewerCloseTrigger</code> <code>XhImageViewerContent</code> <code>XhImageViewerCounter</code> <code>XhImageViewerFlipHorizontalTrigger</code> <code>XhImageViewerFlipVerticalTrigger</code> <code>XhImageViewerImage</code> <code>XhImageViewerNextTrigger</code> <code>XhImageViewerPrevTrigger</code> <code>XhImageViewerResetTrigger</code> <code>XhImageViewerRoot</code> <code>XhImageViewerRotateLeftTrigger</code> <code>XhImageViewerRotateRightTrigger</code> <code>XhImageViewerToolbar</code> <code>XhImageViewerTrigger</code> <code>XhImageViewerViewport</code> <code>XhImageViewerZoomInTrigger</code> <code>XhImageViewerZoomOutTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useImageViewer</code></td></tr><tr><td>状态机</td><td><code>imageViewerMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/image-viewer.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>collection</code></td><td><code>ImageViewerItem[]</code></td><td></td><td>图片清单。看单张就给长度 1 的数组。缺省为空，此时打开也只有工具条与空视口。</td></tr><tr><td><code>open</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>defaultOpen</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>index</code></td><td><code>number</code></td><td></td><td>当前下标（0 起）。给定即受控：内部不再自改，只发 onIndexChange。</td></tr><tr><td><code>defaultIndex</code></td><td><code>number</code></td><td></td><td>非受控初值，默认 0。</td></tr><tr><td><code>loop</code></td><td><code>boolean</code></td><td></td><td>前后翻页到头是否回绕，默认 true。</td></tr><tr><td><code>zoomStep</code></td><td><code>number</code></td><td></td><td>缩放步长（加法），默认 0.5。</td></tr><tr><td><code>minScale</code></td><td><code>number</code></td><td></td><td>缩放下限，默认 0.25。</td></tr><tr><td><code>maxScale</code></td><td><code>number</code></td><td></td><td>缩放上限，默认 8。</td></tr><tr><td><code>closeOnEscape</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>closeOnInteractOutside</code></td><td><code>boolean</code></td><td></td><td>点遮罩（内容之外）关闭，默认 true。</td></tr><tr><td><code>restoreFocus</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>variant</code></td><td><code>OverlayBackdropVariant</code></td><td></td><td>遮罩形态：opaque / blur / transparent。落在 backdrop 上，只换那一层的底色与模糊。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;ImageViewerTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onOpenChange</code></td><td><code>(details: ImageViewerOpenChangeDetails) =&gt; void</code></td><td></td><td>open 变化意图回调；受控时是唯一出口，非受控时随内部转移一并通知。</td></tr><tr><td><code>onIndexChange</code></td><td><code>(details: ImageViewerIndexChangeDetails) =&gt; void</code></td><td></td><td>下标变化意图回调；受控时是唯一出口，非受控随内部写入一并通知。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>open-change</code></td><td><code>ImageViewerOpenChangeDetails</code></td><td>open 状态变化；detail 为 <code>{ open: boolean }</code></td></tr><tr><td><code>index-change</code></td><td><code>ImageViewerIndexChangeDetails</code></td><td>下标变化；detail 为 <code>{ index: number }</code></td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhImageViewerRoot</code></td><td><code>default</code></td><td><code>ImageViewerRootSlotProps</code></td><td></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>backdrop</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>viewport</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>image</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>toolbar</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>counter</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>open</code> · <code>closed</code></p><p><strong>事件</strong>：<code>OPEN</code> · <code>CLOSE</code> · <code>INDEX.SET</code> · <code>INDEX.NEXT</code> · <code>INDEX.PREV</code> · <code>ZOOM.BY</code> · <code>ZOOM.SET</code> · <code>ROTATE.BY</code> · <code>FLIP</code> · <code>TRANSFORM.RESET</code> · <code>IMAGE.LOAD</code> · <code>IMAGE.ERROR</code> · <code>PAN.MOVE</code> · <code>POINTERS.DOWN</code> · <code>POINTERS.CHANGE</code> · <code>POINTERS.END</code> · <code>PAN.END</code> · <code>CONTROLLED.OPEN</code> · <code>CONTROLLED.CLOSE</code></p><p><strong>判据</strong>：<code>isOpenControlled</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>index</code></td><td><code>number</code></td><td>当前下标，恒在 [0, count - 1] 内；清单为空时为 0。</td></tr><tr><td><code>count</code></td><td><code>number</code></td><td></td></tr><tr><td><code>currentItem</code></td><td><code>ImageViewerItem | null</code></td><td>当前那张图；清单为空时为 null。</td></tr><tr><td><code>transform</code></td><td><code>ImageViewerTransform</code></td><td></td></tr><tr><td><code>panning</code></td><td><code>boolean</code></td><td>正在拖拽平移。</td></tr><tr><td><code>imageStatus</code></td><td><code>ImageViewerImageStatus</code></td><td>当前那张大图的取图相位；换图与重开都回到 loading。</td></tr><tr><td><code>canPrev</code></td><td><code>boolean</code></td><td>往前还翻得动（loop 且多于一张时恒为 true）。</td></tr><tr><td><code>canNext</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>setOpen</code></td><td><code>(next: boolean) =&gt; void</code></td><td></td></tr><tr><td><code>setIndex</code></td><td><code>(next: number) =&gt; void</code></td><td>直接跳到某一张；越界会被夹回 [0, count - 1]。换图变换归零。</td></tr><tr><td><code>next</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>prev</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>zoomIn</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>zoomOut</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>setScale</code></td><td><code>(scale: number) =&gt; void</code></td><td></td></tr><tr><td><code>rotateLeft</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>rotateRight</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>flipHorizontal</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>flipVertical</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>reset</code></td><td><code>() =&gt; void</code></td><td>变换整体归零（缩放/旋转/翻转/平移）。</td></tr><tr><td><code>getTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getBackdropProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPositionerProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getImageProps</code></td><td><code>() =&gt; T[&#39;img&#39;]</code></td><td></td></tr><tr><td><code>getToolbarProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>底部那条控件带，装缩放、旋转、翻转与归零这几颗钮。 它报的是 <code>role=group</code>：一组有名字的控件，每颗钮各占一个 Tab 位。 不报 <code>role=toolbar</code>——那个角色承诺条内靠方向键走位，而左右方向键与 Home/End 在这台上是翻页；要那套走位就往这条带里放一个 Toolbar 组件。</td></tr><tr><td><code>getZoomInTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getZoomOutTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getRotateLeftTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getRotateRightTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getFlipHorizontalTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getFlipVerticalTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getResetTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getPrevTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getNextTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getCounterProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCloseTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/dialog-modal/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in trigger</td><td>打开看片浮层并把焦点移入 content</td></tr><tr><td><code>Escape</code></td><td>open</td><td>关闭并把焦点还给 trigger（closeOnEscape=false 时不关）</td></tr><tr><td><code>Tab</code></td><td>open</td><td>在 content 内向后循环焦点</td></tr><tr><td><code>Shift+Tab</code></td><td>open</td><td>在 content 内向前循环焦点</td></tr><tr><td><code>ArrowLeft</code></td><td>open</td><td>上一张</td></tr><tr><td><code>ArrowRight</code></td><td>open</td><td>下一张</td></tr><tr><td><code>Home</code></td><td>open</td><td>跳到第一张</td></tr><tr><td><code>End</code></td><td>open</td><td>跳到最后一张</td></tr><tr><td><code>+</code> / <code>=</code></td><td>open</td><td>放大一档（zoomStep），到 maxScale 停住</td></tr><tr><td><code>-</code></td><td>open</td><td>缩小一档，到 minScale 停住</td></tr><tr><td><code>0</code></td><td>open</td><td>缩放、旋转、翻转与平移一并复位</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>aria-controls</code></td><td><code>content</code> 部件的 id</td></tr><tr><td><code>trigger</code></td><td><code>aria-expanded</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-haspopup</code></td><td>&#39;dialog&#39;</td></tr><tr><td><code>backdrop</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>content</code></td><td><code>aria-hidden</code></td><td>!open || undefined</td></tr><tr><td><code>content</code></td><td><code>aria-label</code></td><td>currentItem?.alt</td></tr><tr><td><code>content</code></td><td><code>aria-modal</code></td><td>&#39;true&#39;</td></tr><tr><td><code>content</code></td><td><code>role</code></td><td>&#39;dialog&#39;</td></tr><tr><td><code>viewport</code></td><td><code>aria-busy</code></td><td>imageStatus === &#39;loading&#39; || undefined</td></tr><tr><td><code>toolbar</code></td><td><code>aria-label</code></td><td>label.toolbar</td></tr><tr><td><code>toolbar</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr><tr><td><code>counter</code></td><td><code>aria-live</code></td><td>&#39;polite&#39;</td></tr></tbody></table><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/image-viewer.css</code> 使用 <code>[data-scope=&quot;image-viewer&quot;][data-part=&quot;trigger&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 与 <code>xihan.motion</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>backdrop</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>backdrop</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>positioner</code></td><td><code>data-positioned</code></td><td>&#39;&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>viewport</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>viewport</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>viewport</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>image</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>image</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>image</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>toolbar</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>counter</code></td><td><code>data-count</code></td><td>String(count)</td></tr><tr><td><code>counter</code></td><td><code>data-index</code></td><td>String(index + 1)</td></tr><tr><td><code>counter</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-image-viewer-action-bg-active</code></td><td><code>flip-horizontal-trigger</code><br><code>flip-vertical-trigger</code><br><code>next-trigger</code><br><code>prev-trigger</code><br><code>reset-trigger</code><br><code>rotate-left-trigger</code><br><code>rotate-right-trigger</code><br><code>zoom-in-trigger</code><br><code>zoom-out-trigger</code></td><td><code>background</code></td><td><code>active</code><br><code>not(:disabled)</code></td><td><code>--xh-color-neutral-950</code></td><td>image-viewer 的 flip-horizontal-trigger、flip-vertical-trigger、next-trigger、prev-trigger、reset-trigger、rotate-left-trigger、rotate-right-trigger、zoom-in-trigger、zoom-out-trigger 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-image-viewer-action-bg-hover</code></td><td><code>flip-horizontal-trigger</code><br><code>flip-vertical-trigger</code><br><code>next-trigger</code><br><code>prev-trigger</code><br><code>reset-trigger</code><br><code>rotate-left-trigger</code><br><code>rotate-right-trigger</code><br><code>zoom-in-trigger</code><br><code>zoom-out-trigger</code></td><td><code>background</code></td><td><code>hover</code><br><code>not(:disabled)</code></td><td><code>--xh-color-neutral-950</code></td><td>image-viewer 的 flip-horizontal-trigger、flip-vertical-trigger、next-trigger、prev-trigger、reset-trigger、rotate-left-trigger、rotate-right-trigger、zoom-in-trigger、zoom-out-trigger 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-image-viewer-backdrop-bg</code></td><td><code>backdrop</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-color-neutral-950</code></td><td>image-viewer 的 backdrop 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-image-viewer-backdrop-blur</code></td><td><code>backdrop</code></td><td><code>backdrop-filter</code></td><td><code>variant=blur</code></td><td><code>--xh-overlay-backdrop-blur</code></td><td>image-viewer 的 backdrop 部件 backdrop-filter 覆盖槽。</td></tr><tr><td><code>--xh-image-viewer-backdrop-layer</code></td><td><code>backdrop</code></td><td><code>z-index</code></td><td><code>default</code></td><td><code>--xh-_layer</code></td><td>image-viewer 的 backdrop 部件 z-index 覆盖槽。</td></tr><tr><td><code>--xh-image-viewer-chrome-bg</code></td><td><code>close-trigger</code><br><code>counter</code><br><code>next-trigger</code><br><code>prev-trigger</code><br><code>toolbar</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-color-neutral-950</code></td><td>image-viewer 的 close-trigger、counter、next-trigger、prev-trigger、toolbar 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-image-viewer-close-bg-active</code></td><td><code>close-trigger</code></td><td><code>background</code></td><td><code>active</code></td><td><code>--xh-color-neutral-950</code></td><td>image-viewer 的 close-trigger 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-image-viewer-close-bg-hover</code></td><td><code>close-trigger</code></td><td><code>background</code></td><td><code>hover</code><br><code>not(:disabled)</code></td><td><code>--xh-color-neutral-950</code></td><td>image-viewer 的 close-trigger 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-image-viewer-close-radius</code></td><td><code>close-trigger</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-control</code></td><td>image-viewer 的 close-trigger 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-image-viewer-close-size</code></td><td><code>close-trigger</code></td><td><code>block-size</code><br><code>inline-size</code></td><td><code>default</code></td><td><code>--xh-control-h-lg</code></td><td>image-viewer 的 close-trigger 部件 block-size、inline-size 覆盖槽。</td></tr><tr><td><code>--xh-image-viewer-counter-padding</code></td><td><code>counter</code></td><td><code>padding</code></td><td><code>default</code></td><td><code>--xh-space-1</code></td><td>image-viewer 的 counter 部件 padding 覆盖槽。</td></tr><tr><td><code>--xh-image-viewer-fg</code></td><td><code>content</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-color-neutral-0</code></td><td>image-viewer 的 content 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-image-viewer-icon-size</code></td><td><code>content</code></td><td><code>--xh-icon-size</code></td><td><code>default</code></td><td><code>--xh-glyph-size-text</code></td><td>image-viewer 的 content 部件 --xh-icon-size 覆盖槽。</td></tr><tr><td><code>--xh-image-viewer-layer</code></td><td><code>positioner</code></td><td><code>z-index</code></td><td><code>default</code></td><td><code>--xh-_layer</code></td><td>image-viewer 的 positioner 部件 z-index 覆盖槽。</td></tr><tr><td><code>--xh-image-viewer-loading-bg</code></td><td><code>viewport</code></td><td><code>background</code></td><td><code>loading</code></td><td><code>--xh-bg-surface-raised</code></td><td>image-viewer 的 viewport 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-image-viewer-loading-radius</code></td><td><code>viewport</code></td><td><code>border-radius</code></td><td><code>loading</code></td><td><code>--xh-shape-surface</code></td><td>image-viewer 的 viewport 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-image-viewer-loading-size</code></td><td><code>viewport</code></td><td><code>block-size</code><br><code>inline-size</code></td><td><code>loading</code></td><td><code>--xh-control-h-lg</code></td><td>image-viewer 的 viewport 部件 block-size、inline-size 覆盖槽。</td></tr><tr><td><code>--xh-image-viewer-overlay-radius</code></td><td><code>counter</code><br><code>next-trigger</code><br><code>prev-trigger</code><br><code>toolbar</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-pill</code></td><td>image-viewer 的 counter、next-trigger、prev-trigger、toolbar 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-image-viewer-toolbar-gap</code></td><td><code>toolbar</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-1</code></td><td>image-viewer 的 toolbar 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-image-viewer-toolbar-padding</code></td><td><code>toolbar</code></td><td><code>padding</code></td><td><code>default</code></td><td><code>--xh-space-1_5</code></td><td>image-viewer 的 toolbar 部件 padding 覆盖槽。</td></tr><tr><td><code>--xh-image-viewer-toolbar-radius</code></td><td><code>toolbar</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-control</code></td><td>image-viewer 的 toolbar 部件 border-radius 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>关键帧 <code>xh-fade-in</code> · <code>xh-fade-out</code> 随皮肤自带，不引用别处文件里的名字；<code>background</code> · <code>scale</code> · <code>transform</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>皮肤之外还有一段：退场由适配器的退场闸门把关，动画播完才真收起。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p>',56))])}const w=a(g,[["render",h]]);export{v as __pageData,w as default};
